-- Optional: the app creates these automatically on first page load.
ALTER TABLE competitions ADD COLUMN `format` ENUM('League','Groups') NOT NULL DEFAULT 'League' AFTER `type`;
CREATE TABLE IF NOT EXISTS comp_teams (id INT UNSIGNED NOT NULL AUTO_INCREMENT, competition_id INT UNSIGNED NOT NULL, team_name VARCHAR(100) NOT NULL, group_name VARCHAR(30) DEFAULT NULL, PRIMARY KEY (id), UNIQUE KEY uq_comp_team (competition_id, team_name), CONSTRAINT fk_ct_comp FOREIGN KEY (competition_id) REFERENCES competitions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS comp_matches (id INT UNSIGNED NOT NULL AUTO_INCREMENT, competition_id INT UNSIGNED NOT NULL, stage VARCHAR(30) DEFAULT NULL, match_date DATE DEFAULT NULL, home_team VARCHAR(100) NOT NULL, away_team VARCHAR(100) NOT NULL, home_score TINYINT UNSIGNED DEFAULT NULL, away_score TINYINT UNSIGNED DEFAULT NULL, PRIMARY KEY (id), KEY idx_cm_comp (competition_id), CONSTRAINT fk_cm_comp FOREIGN KEY (competition_id) REFERENCES competitions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- v2: league/group rules, suspension, point deductions, knockout (also applied automatically by the app)
ALTER TABLE competitions ADD COLUMN max_teams SMALLINT UNSIGNED DEFAULT NULL, ADD COLUMN num_groups TINYINT UNSIGNED DEFAULT NULL, ADD COLUMN teams_per_group TINYINT UNSIGNED DEFAULT NULL, ADD COLUMN qualify_per_group TINYINT UNSIGNED NOT NULL DEFAULT 2, ADD COLUMN knockout TINYINT(1) NOT NULL DEFAULT 0, ADD COLUMN ko_teams TINYINT UNSIGNED DEFAULT NULL;
ALTER TABLE comp_teams ADD COLUMN status ENUM('active','suspended') NOT NULL DEFAULT 'active', ADD COLUMN point_adjust SMALLINT NOT NULL DEFAULT 0, ADD COLUMN adjust_reason VARCHAR(150) DEFAULT NULL;
CREATE TABLE IF NOT EXISTS comp_ko (id INT UNSIGNED NOT NULL AUTO_INCREMENT, competition_id INT UNSIGNED NOT NULL, round_no TINYINT UNSIGNED NOT NULL, slot TINYINT UNSIGNED NOT NULL, team_a VARCHAR(100) DEFAULT NULL, team_b VARCHAR(100) DEFAULT NULL, score_a TINYINT UNSIGNED DEFAULT NULL, score_b TINYINT UNSIGNED DEFAULT NULL, pen_a TINYINT UNSIGNED DEFAULT NULL, pen_b TINYINT UNSIGNED DEFAULT NULL, match_date DATE DEFAULT NULL, PRIMARY KEY (id), UNIQUE KEY uq_ko (competition_id, round_no, slot), CONSTRAINT fk_ko_comp FOREIGN KEY (competition_id) REFERENCES competitions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
